(()=>{"use strict";const{add,n,p,u,i,text,row:R,check,nums,sum,PI,rad,deg}=CMModels,D=(s,name,purpose,f,calc,formula,e,note="Idealized SI-unit educational model. Real components, tolerances, losses and safe operating limits require separate verification.|\u4F7F\u7528 SI \u5355\u4F4D\u7684\u7406\u60F3\u6559\u80B2\u6A21\u578B\uFF1B\u5B9E\u9645\u5143\u4EF6\u3001\u5BB9\u5DEE\u3001\u635F\u8017\u4E0E\u5B89\u5168\u5DE5\u4F5C\u754C\u9650\u9700\u8981\u53E6\u884C\u6838\u5B9E\u3002")=>add(s,name,"Science",purpose,f,calc,formula,e,note),hz=n("f","Frequency (Hz)|\u9891\u7387\uFF08Hz\uFF09",50),ke=89875517923e-1,h=662607015e-42,c=299792458,eV=1602176634e-28,positiveList=s=>{const a=nums(s);return check(a.every(x=>x>0),"All component values must be positive.|\u6240\u6709\u5143\u4EF6\u503C\u5E94\u5927\u4E8E\u96F6\u3002"),a};D("electric-power","DC Electric Power|\u76F4\u6D41\u7535\u529F\u7387","Calculate electrical power and energy from voltage and current.|\u7531\u7535\u538B\u4E0E\u7535\u6D41\u8BA1\u7B97\u7535\u529F\u7387\u548C\u8017\u80FD\u3002",[n("v","Voltage (V)|\u7535\u538B\uFF08V\uFF09",12),n("i","Current (A)|\u7535\u6D41\uFF08A\uFF09",2),n("t","Operating time (hours)|\u5DE5\u4F5C\u65F6\u957F\uFF08\u5C0F\u65F6\uFF09",5)],v=>[R("Physical power|\u529F\u7387",v.v*v.i,"W"),R("Energy consumed|\u8017\u7535\u91CF",v.v*v.i*v.t/1e3,"kWh")],"Use P = VI and E = Pt/1000. V is voltage in V, I is current in A, and t is operating hours. Power P is in W and consumed energy E is in kWh.|\u4F7F\u7528 P = VI \u53CA E = Pt/1000\u3002\u53D8\u91CF V \u4E3A\u7535\u538B\uFF08V\uFF09\uFF0CI \u4E3A\u7535\u6D41\uFF08A\uFF09\uFF0Ct \u4E3A\u5DE5\u4F5C\u5C0F\u65F6\uFF1B\u529F\u7387 P \u7684\u5355\u4F4D\u4E3A W\uFF0C\u8017\u7535\u91CF E \u7684\u5355\u4F4D\u4E3A kWh\u3002",[24,.12]),D("series-resistance","Series Resistance|\u4E32\u8054\u7535\u963B","Add ideal resistors carrying the same current.|\u5408\u5E76\u627F\u8F7D\u76F8\u540C\u7535\u6D41\u7684\u7406\u60F3\u4E32\u8054\u7535\u963B\u3002",[text("x","Resistor values (\u03A9)|\u5404\u7535\u963B\uFF08\u03A9\uFF09","1,2,3")],v=>[R("Equivalent resistance|\u7B49\u6548\u7535\u963B",sum(positiveList(v.x)),"\u03A9")],"Use R\u2091 = \u03A3R\u1D62. Each R\u1D62 is a positive series resistor value in \u03A9. The equivalent resistance R\u2091 uses the same unit; the sum covers every entered resistor.|\u4F7F\u7528 R\u2091 = \u03A3R\u1D62\u3002\u6BCF\u4E2A R\u1D62 \u4E3A\u6B63\u7684\u4E32\u8054\u7535\u963B\u503C\uFF08\u03A9\uFF09\uFF1B\u7B49\u6548\u7535\u963B R\u2091 \u4F7F\u7528\u76F8\u540C\u5355\u4F4D\uFF0C\u5BF9\u6240\u6709\u81EA\u586B\u7535\u963B\u6C42\u548C\u3002",[6]),D("parallel-resistance","Parallel Resistance|\u5E76\u8054\u7535\u963B","Combine ideal resistors sharing the same voltage.|\u5408\u5E76\u627F\u53D7\u76F8\u540C\u7535\u538B\u7684\u7406\u60F3\u5E76\u8054\u7535\u963B\u3002",[text("x","Resistor values (\u03A9)|\u5404\u7535\u963B\uFF08\u03A9\uFF09","10,20")],v=>[R("Equivalent resistance|\u7B49\u6548\u7535\u963B",1/sum(positiveList(v.x).map(x=>1/x)),"\u03A9")],"Use R\u2091 = 1/\u03A3(1/R\u1D62). Each R\u1D62 is a positive parallel resistor value in \u03A9. Sum their reciprocals, then take the reciprocal again for equivalent resistance R\u2091.|\u4F7F\u7528 R\u2091 = 1/\u03A3(1/R\u1D62)\u3002\u6BCF\u4E2A R\u1D62 \u4E3A\u6B63\u7684\u5E76\u8054\u7535\u963B\u503C\uFF08\u03A9\uFF09\uFF1B\u5148\u5C06\u5012\u6570\u76F8\u52A0\uFF0C\u518D\u53D6\u5012\u6570\uFF0C\u5F97\u5230\u7B49\u6548\u7535\u963B R\u2091\u3002",[20/3]),D("voltage-divider","Voltage Divider|\u7535\u963B\u5206\u538B","Find unloaded output voltage across the lower divider resistor.|\u6C42\u65E0\u8D1F\u8F7D\u5206\u538B\u5668\u4E0B\u4FA7\u7535\u963B\u7535\u538B\u3002",[u("v","Input voltage (V)|\u8F93\u5165\u7535\u538B\uFF08V\uFF09",12),p("a","Upper resistor R1 (\u03A9)|\u4E0A\u4FA7\u7535\u963B R1\uFF08\u03A9\uFF09",1e3),p("b","Lower resistor R2 (\u03A9)|\u4E0B\u4FA7\u7535\u963B R2\uFF08\u03A9\uFF09",2e3)],v=>[R("Unloaded output voltage|\u65E0\u8D1F\u8F7D\u8F93\u51FA\u7535\u538B",v.v*v.b/(v.a+v.b),"V")],"Use V\u2092 = V\u1D62R\u2082/(R\u2081+R\u2082). V\u1D62 is input voltage, R\u2081 is the upper resistor, and R\u2082 is the lower resistor in the same resistance unit. Output V\u2092 is measured across the lower resistor without a load.|\u4F7F\u7528 V\u2092 = V\u1D62R\u2082/(R\u2081+R\u2082)\u3002V\u1D62 \u4E3A\u8F93\u5165\u7535\u538B\uFF0CR\u2081 \u4E3A\u4E0A\u4FA7\u7535\u963B\uFF0CR\u2082 \u4E3A\u540C\u7535\u963B\u5355\u4F4D\u7684\u4E0B\u4FA7\u7535\u963B\uFF1B\u8F93\u51FA V\u2092 \u4E3A\u65E0\u8D1F\u8F7D\u65F6\u4E0B\u4FA7\u7535\u963B\u4E24\u7AEF\u7535\u538B\u3002",[8],"Assumes no output load. A load changes the lower equivalent resistance and output.|\u5047\u8BBE\u8F93\u51FA\u65E0\u8D1F\u8F7D\uFF1B\u8D1F\u8F7D\u4F1A\u6539\u53D8\u4E0B\u4FA7\u7B49\u6548\u7535\u963B\u4E0E\u8F93\u51FA\u3002"),D("current-divider","Current Divider|\u7535\u6D41\u5206\u6D41","Split total current between two parallel resistors.|\u8BA1\u7B97\u4E24\u4E2A\u5E76\u8054\u7535\u963B\u7684\u652F\u8DEF\u7535\u6D41\u3002",[u("i","Total current (A)|\u603B\u7535\u6D41\uFF08A\uFF09",3),p("a","Branch A resistance (\u03A9)|A \u652F\u8DEF\u7535\u963B\uFF08\u03A9\uFF09",10),p("b","Branch B resistance (\u03A9)|B \u652F\u8DEF\u7535\u963B\uFF08\u03A9\uFF09",20)],v=>[R("Branch A current|A \u652F\u8DEF\u7535\u6D41",v.i*v.b/(v.a+v.b),"A"),R("Branch B current|B \u652F\u8DEF\u7535\u6D41",v.i*v.a/(v.a+v.b),"A")],"Use I\u2090 = IR\u1D66/(R\u2090+R\u1D66) and I\u1D66 = IR\u2090/(R\u2090+R\u1D66). I is total current. R\u2090 and R\u1D66 are the parallel branch resistances in the same unit; each current result uses the input current unit.|\u4F7F\u7528 I\u2090 = IR\u1D66/(R\u2090+R\u1D66) \u53CA I\u1D66 = IR\u2090/(R\u2090+R\u1D66)\u3002I \u4E3A\u603B\u7535\u6D41\uFF0CR\u2090 \u4E0E R\u1D66 \u4E3A\u540C\u5355\u4F4D\u5E76\u8054\u652F\u8DEF\u7535\u963B\uFF1B\u5404\u652F\u8DEF\u7535\u6D41\u4F7F\u7528\u8F93\u5165\u7535\u6D41\u7684\u5355\u4F4D\u3002",[2,1]),D("capacitor-energy","Capacitor Energy|\u7535\u5BB9\u50A8\u80FD","Calculate charge and stored energy in an ideal capacitor.|\u8BA1\u7B97\u7406\u60F3\u7535\u5BB9\u7684\u7535\u8377\u4E0E\u50A8\u80FD\u3002",[n("c","Capacitance (\xB5F)|\u7535\u5BB9\u91CF\uFF08\xB5F\uFF09",1e3),u("v","Voltage (V)|\u7535\u538B\uFF08V\uFF09",12)],v=>[R("Stored energy|\u50A8\u5B58\u80FD\u91CF",.5*v.c*1e-6*v.v*v.v,"J"),R("Charge|\u7535\u8377\u91CF",v.c*1e-6*v.v,"C")],"E=\xBDCV\xB2; Q=CV",[.072,.012]),D("series-capacitance","Series Capacitance|\u4E32\u8054\u7535\u5BB9","Combine ideal capacitors in series.|\u5408\u5E76\u7406\u60F3\u4E32\u8054\u7535\u5BB9\u3002",[text("x","Capacitor values (\xB5F)|\u5404\u7535\u5BB9\uFF08\xB5F\uFF09","10,20")],v=>[R("Equivalent capacitance|\u7B49\u6548\u7535\u5BB9",1/sum(positiveList(v.x).map(x=>1/x)),"\xB5F")],"Use C\u2091 = 1/\u03A3(1/C\u1D62). Each C\u1D62 is a positive series capacitance in \xB5F. Sum reciprocals and take the reciprocal again; equivalent capacitance C\u2091 remains in \xB5F.|\u4F7F\u7528 C\u2091 = 1/\u03A3(1/C\u1D62)\u3002\u6BCF\u4E2A C\u1D62 \u4E3A\u6B63\u7684\u4E32\u8054\u7535\u5BB9\u503C\uFF08\xB5F\uFF09\uFF1B\u5148\u5C06\u5012\u6570\u76F8\u52A0\u518D\u53D6\u5012\u6570\uFF0C\u7B49\u6548\u7535\u5BB9 C\u2091 \u4ECD\u4F7F\u7528 \xB5F\u3002",[20/3]),D("parallel-capacitance","Parallel Capacitance|\u5E76\u8054\u7535\u5BB9","Combine ideal capacitors in parallel.|\u5408\u5E76\u7406\u60F3\u5E76\u8054\u7535\u5BB9\u3002",[text("x","Capacitor values (\xB5F)|\u5404\u7535\u5BB9\uFF08\xB5F\uFF09","10,20")],v=>[R("Equivalent capacitance|\u7B49\u6548\u7535\u5BB9",sum(positiveList(v.x)),"\xB5F")],"Use C\u2091 = \u03A3C\u1D62. Each C\u1D62 is a positive parallel capacitance in \xB5F. Sum all entered values for equivalent capacitance C\u2091 in the same unit.|\u4F7F\u7528 C\u2091 = \u03A3C\u1D62\u3002\u6BCF\u4E2A C\u1D62 \u4E3A\u6B63\u7684\u5E76\u8054\u7535\u5BB9\u503C\uFF08\xB5F\uFF09\uFF1B\u5C06\u6240\u6709\u8F93\u5165\u503C\u76F8\u52A0\uFF0C\u5F97\u5230\u76F8\u540C\u5355\u4F4D\u7684\u7B49\u6548\u7535\u5BB9 C\u2091\u3002",[30]),D("rc-time-constant","RC Time Constant|RC \u65F6\u95F4\u5E38\u6570","Find capacitor charging time scales for an ideal RC circuit.|\u6C42\u7406\u60F3 RC \u7535\u8DEF\u7535\u5BB9\u5145\u7535\u7684\u65F6\u95F4\u5C3A\u5EA6\u3002",[n("r","Resistance (\u03A9)|\u7535\u963B\uFF08\u03A9\uFF09",1e3),n("c","Capacitance (\xB5F)|\u7535\u5BB9\uFF08\xB5F\uFF09",100)],v=>[R("Time constant|\u65F6\u95F4\u5E38\u6570",v.r*v.c*1e-6,"s"),R("Time to 99% of step voltage|\u8FBE\u5230\u9636\u8DC3\u7535\u538B 99% \u7528\u65F6",-Math.log(.01)*v.r*v.c*1e-6,"s")],"\u03C4=RC; t99=\u2212\u03C4ln(0.01)",[.1,.460517018598809]),D("rl-time-constant","RL Time Constant|RL \u65F6\u95F4\u5E38\u6570","Find current rise time scales in an ideal series RL circuit.|\u6C42\u7406\u60F3\u4E32\u8054 RL \u7535\u8DEF\u7535\u6D41\u4E0A\u5347\u65F6\u95F4\u5C3A\u5EA6\u3002",[n("l","Inductance (mH)|\u7535\u611F\uFF08mH\uFF09",100),p("r","Total series resistance (\u03A9)|\u603B\u4E32\u8054\u7535\u963B\uFF08\u03A9\uFF09",10)],v=>[R("Time constant|\u65F6\u95F4\u5E38\u6570",v.l/1e3/v.r,"s"),R("Time to 99% of final current|\u8FBE\u5230\u6700\u7EC8\u7535\u6D41 99% \u7528\u65F6",-Math.log(.01)*v.l/1e3/v.r,"s")],"\u03C4=L/R",[.01,.0460517018598809]),D("lc-resonance","LC Resonant Frequency|LC \u8C10\u632F\u9891\u7387","Find natural resonance of ideal inductance and capacitance.|\u6C42\u7406\u60F3\u7535\u611F\u7535\u5BB9\u7684\u56FA\u6709\u8C10\u632F\u9891\u7387\u3002",[p("l","Inductance (mH)|\u7535\u611F\uFF08mH\uFF09",10),p("c","Capacitance (nF)|\u7535\u5BB9\uFF08nF\uFF09",100)],v=>[R("Resonant frequency|\u8C10\u632F\u9891\u7387",1/(2*PI*Math.sqrt(v.l*.001*v.c*1e-9)),"Hz")],"f\u2080=1/(2\u03C0\u221ALC)",[5032.921210448704]),D("inductive-reactance","Inductive Reactance|\u611F\u6297","Calculate frequency-dependent ideal inductor reactance.|\u8BA1\u7B97\u7406\u60F3\u7535\u611F\u968F\u9891\u7387\u53D8\u5316\u7684\u611F\u6297\u3002",[hz,n("l","Inductance (mH)|\u7535\u611F\uFF08mH\uFF09",100)],v=>[R("Inductive reactance|\u611F\u6297",2*PI*v.f*v.l/1e3,"\u03A9")],"XL=2\u03C0fL",[10*PI]),D("capacitive-reactance","Capacitive Reactance|\u5BB9\u6297","Calculate ideal capacitor reactance at a positive frequency.|\u8BA1\u7B97\u6B63\u9891\u7387\u4E0B\u7406\u60F3\u7535\u5BB9\u7684\u5BB9\u6297\u3002",[p("f","Frequency (Hz)|\u9891\u7387\uFF08Hz\uFF09",50),p("c","Capacitance (\xB5F)|\u7535\u5BB9\uFF08\xB5F\uFF09",100)],v=>[R("Capacitive reactance magnitude|\u5BB9\u6297\u5927\u5C0F",1/(2*PI*v.f*v.c*1e-6),"\u03A9")],"|XC|=1/(2\u03C0fC)",[100/PI]),D("ac-series-impedance","AC Series Impedance|\u4EA4\u6D41\u4E32\u8054\u963B\u6297","Combine resistance and opposing series reactances.|\u5408\u5E76\u7535\u963B\u53CA\u76F8\u53CD\u65B9\u5411\u7684\u4E32\u8054\u7535\u6297\u3002",[n("r","Resistance (\u03A9)|\u7535\u963B\uFF08\u03A9\uFF09",30),n("l","Inductive reactance (\u03A9)|\u611F\u6297\uFF08\u03A9\uFF09",40),n("c","Capacitive reactance magnitude (\u03A9)|\u5BB9\u6297\u5927\u5C0F\uFF08\u03A9\uFF09",0)],v=>{const x=v.l-v.c,z=Math.hypot(v.r,x);return check(z>0,"Zero impedance has no defined phase angle.|\u96F6\u963B\u6297\u6CA1\u6709\u786E\u5B9A\u76F8\u4F4D\u89D2\u3002"),[R("Impedance magnitude|\u963B\u6297\u5927\u5C0F",z,"\u03A9"),R("Impedance phase|\u963B\u6297\u76F8\u4F4D",deg(Math.atan2(x,v.r)),"\xB0"),R("Power factor magnitude|\u529F\u7387\u56E0\u6570\u5927\u5C0F",v.r/z)]},"Z=R+j(XL\u2212XC); |Z|=\u221A[R\xB2+(XL\u2212XC)\xB2]",[50,53.13010235415598,.6]),D("electric-charge-flow","Electric Charge from Current|\u7535\u6D41\u7535\u8377\u91CF","Integrate a constant or average electric current over time.|\u5C06\u6052\u5B9A\u6216\u5E73\u5747\u7535\u6D41\u4E58\u4EE5\u6301\u7EED\u65F6\u95F4\u3002",[u("i","Average current (A)|\u5E73\u5747\u7535\u6D41\uFF08A\uFF09",2),n("t","Duration (s)|\u6301\u7EED\u65F6\u95F4\uFF08s\uFF09",60)],v=>[R("Charge transferred|\u901A\u8FC7\u7535\u8377\u91CF",v.i*v.t,"C"),R("Charge in ampere hours|\u5B89\u65F6\u7535\u91CF",v.i*v.t/3600,"Ah")],"Q=It",[120,1/30]),D("coulomb-force","Coulomb Force|\u5E93\u4ED1\u529B","Find electrostatic force magnitude between point charges in vacuum.|\u6C42\u771F\u7A7A\u4E2D\u70B9\u7535\u8377\u95F4\u7684\u9759\u7535\u529B\u5927\u5C0F\u3002",[u("a","Charge A (\xB5C)|\u7535\u8377 A\uFF08\xB5C\uFF09",2),u("b","Charge B (\xB5C)|\u7535\u8377 B\uFF08\xB5C\uFF09",3),p("r","Separation (m)|\u8DDD\u79BB\uFF08m\uFF09",.1)],v=>[R("Force magnitude|\u529B\u5927\u5C0F",ke*Math.abs(v.a*v.b)*1e-12/v.r**2,"N"),R("Interaction|\u76F8\u4E92\u4F5C\u7528",v.a*v.b>0?"Repulsive|\u6392\u65A5":v.a*v.b<0?"Attractive|\u5438\u5F15":"No electrostatic interaction|\u65E0\u9759\u7535\u76F8\u4E92\u4F5C\u7528")],"|F|=ke|q\u2081q\u2082|/r\xB2",[5.39253107538,"Repulsive|\u6392\u65A5"]),D("point-charge-field","Point Charge Electric Field|\u70B9\u7535\u8377\u7535\u573A","Find the radial electric field of a point charge in vacuum.|\u6C42\u771F\u7A7A\u70B9\u7535\u8377\u7684\u5F84\u5411\u7535\u573A\u3002",[u("q","Charge (nC)|\u7535\u8377\uFF08nC\uFF09",1),p("r","Radial distance (m)|\u5F84\u5411\u8DDD\u79BB\uFF08m\uFF09",.1)],v=>[R("Outward signed electric field|\u5411\u5916\u4E3A\u6B63\u7684\u7535\u573A",ke*v.q*1e-9/v.r**2,"N/C")],"Er=ke q/r\xB2",[898.75517923]),D("magnetic-charge-force","Magnetic Force on a Charge|\u8FD0\u52A8\u7535\u8377\u78C1\u529B","Find magnetic force magnitude from velocity and field angle.|\u7531\u901F\u5EA6\u4E0E\u78C1\u573A\u5939\u89D2\u6C42\u78C1\u529B\u5927\u5C0F\u3002",[u("q","Charge (\xB5C)|\u7535\u8377\uFF08\xB5C\uFF09",2),n("v","Speed (m/s)|\u901F\u7387\uFF08m/s\uFF09",1e3),n("b","Magnetic flux density (T)|\u78C1\u611F\u5E94\u5F3A\u5EA6\uFF08T\uFF09",.5),n("a","Velocity-field angle (degrees)|\u901F\u5EA6\u4E0E\u78C1\u573A\u5939\u89D2\uFF08\u5EA6\uFF09",90,0,180)],v=>[R("Magnetic force magnitude|\u78C1\u529B\u5927\u5C0F",Math.abs(v.q)*1e-6*v.v*v.b*Math.sin(rad(v.a)),"N")],"Use F = abs(q)vB sin\u03B8. q is charge converted from \xB5C to C, v is speed in m/s, B is magnetic flux density in T, and \u03B8 is the velocity-field angle in degrees. abs means absolute value; force magnitude is in N.|\u4F7F\u7528 F = abs(q)vB sin\u03B8\u3002q \u4E3A\u4ECE \xB5C \u6362\u7B97\u6210 C \u7684\u7535\u8377\uFF0Cv \u4E3A\u901F\u7387\uFF08m/s\uFF09\uFF0CB \u4E3A\u78C1\u611F\u5E94\u5F3A\u5EA6\uFF08T\uFF09\uFF0C\u03B8 \u4E3A\u901F\u5EA6\u4E0E\u78C1\u573A\u5939\u89D2\uFF08\u5EA6\uFF09\uFF1Babs \u8868\u793A\u7EDD\u5BF9\u503C\uFF0C\u529B\u5927\u5C0F\u7684\u5355\u4F4D\u4E3A N\u3002",[.001]),D("ideal-transformer","Ideal Transformer Ratio|\u7406\u60F3\u53D8\u538B\u5668\u53D8\u6BD4","Convert AC voltage by primary and secondary winding counts.|\u6309\u521D\u6B21\u7EA7\u531D\u6570\u6362\u7B97\u4EA4\u6D41\u7535\u538B\u3002",[n("v","Primary RMS voltage (V)|\u521D\u7EA7\u6709\u6548\u7535\u538B\uFF08V\uFF09",230),i("p","Primary turns|\u521D\u7EA7\u531D\u6570",1e3,1,1e6),i("s","Secondary turns|\u6B21\u7EA7\u531D\u6570",100,1,1e6)],v=>[R("Secondary RMS voltage|\u6B21\u7EA7\u6709\u6548\u7535\u538B",v.v*v.s/v.p,"V"),R("Primary / secondary turns|\u521D\u6B21\u7EA7\u531D\u6570\u6BD4",v.p/v.s)],"Vs/Vp=Ns/Np",[23,10],"Ideal AC transformer; excludes losses, saturation, insulation and current ratings. Not applicable to steady DC.|\u7406\u60F3\u4EA4\u6D41\u53D8\u538B\u5668\uFF0C\u5FFD\u7565\u635F\u8017\u3001\u9971\u548C\u3001\u7EDD\u7F18\u4E0E\u989D\u5B9A\u7535\u6D41\uFF0C\u4E0D\u9002\u7528\u4E8E\u7A33\u6001\u76F4\u6D41\u3002"),D("battery-runtime","Battery Runtime Estimate|\u7535\u6C60\u7EED\u822A\u4F30\u7B97","Estimate usable energy and constant-load runtime.|\u4F30\u8BA1\u53EF\u7528\u7535\u91CF\u4E0E\u6052\u5B9A\u8D1F\u8F7D\u7EED\u822A\u3002",[p("v","Nominal battery voltage (V)|\u7535\u6C60\u6807\u79F0\u7535\u538B\uFF08V\uFF09",12),n("a","Capacity (Ah)|\u5BB9\u91CF\uFF08Ah\uFF09",100),n("d","Usable depth of discharge (%)|\u53EF\u7528\u653E\u7535\u6DF1\u5EA6\uFF08%\uFF09",80,0,100),n("e","Conversion efficiency (%)|\u8F6C\u6362\u6548\u7387\uFF08%\uFF09",90,0,100),p("p","Constant load power (W)|\u6052\u5B9A\u8D1F\u8F7D\u529F\u7387\uFF08W\uFF09",100)],v=>{const e=v.v*v.a*v.d/100*v.e/100;return[R("Estimated runtime|\u4F30\u8BA1\u7EED\u822A",e/v.p,"hours"),R("Delivered usable energy|\u8F93\u51FA\u53EF\u7528\u80FD\u91CF",e,"Wh")]},"Use t = VCf\u03B7/P. V is nominal voltage in V, C is capacity in Ah, f is usable discharge fraction, \u03B7 is conversion efficiency as a fraction, and P is constant load in W. Runtime t is in hours.|\u4F7F\u7528 t = VCf\u03B7/P\u3002\u53D8\u91CF V \u4E3A\u6807\u79F0\u7535\u538B\uFF08V\uFF09\uFF0CC \u4E3A\u5BB9\u91CF\uFF08Ah\uFF09\uFF0Cf \u4E3A\u53EF\u7528\u653E\u7535\u6BD4\u4F8B\uFF0C\u03B7 \u4E3A\u8F6C\u6362\u6548\u7387\u7684\u5C0F\u6570\u6BD4\u4F8B\uFF0CP \u4E3A\u6052\u5B9A\u8D1F\u8F7D\uFF08W\uFF09\uFF1B\u7EED\u822A t \u7684\u5355\u4F4D\u4E3A\u5C0F\u65F6\u3002",[8.64,864],"Ignores rate-dependent capacity, ageing, temperature, voltage sag, standby losses and battery management limits.|\u5FFD\u7565\u500D\u7387\u5BB9\u91CF\u53D8\u5316\u3001\u8001\u5316\u3001\u6E29\u5EA6\u3001\u538B\u964D\u3001\u5F85\u673A\u635F\u8017\u4E0E\u7535\u6C60\u7BA1\u7406\u9650\u5236\u3002"),D("wave-speed","Wave Speed|\u6CE2\u901F","Combine frequency and wavelength.|\u7ED3\u5408\u9891\u7387\u4E0E\u6CE2\u957F\u6C42\u6CE2\u901F\u3002",[n("f","Frequency (Hz)|\u9891\u7387\uFF08Hz\uFF09",50),n("l","Wavelength (m)|\u6CE2\u957F\uFF08m\uFF09",2)],v=>[R("Wave speed|\u6CE2\u901F",v.f*v.l,"m/s")],"v=f\u03BB",[100]),D("doppler-frequency","Doppler Observed Frequency|\u591A\u666E\u52D2\u89C2\u6D4B\u9891\u7387","Estimate a sound-frequency shift along one line.|\u4F30\u8BA1\u4E00\u6761\u76F4\u7EBF\u4E0A\u7684\u58F0\u9891\u53D8\u5316\u3002",[p("f","Emitted frequency (Hz)|\u53D1\u5C04\u9891\u7387\uFF08Hz\uFF09",1e3),p("c","Sound speed in medium (m/s)|\u4ECB\u8D28\u58F0\u901F\uFF08m/s\uFF09",343),u("o","Observer speed toward source (m/s)|\u89C2\u5BDF\u8005\u671D\u5411\u58F0\u6E90\u901F\u5EA6\uFF08m/s\uFF09",0),u("s","Source speed toward observer (m/s)|\u58F0\u6E90\u671D\u5411\u89C2\u5BDF\u8005\u901F\u5EA6\uFF08m/s\uFF09",34.3)],v=>(check(Math.abs(v.o)<v.c&&Math.abs(v.s)<v.c,"Use subsonic speeds relative to the medium.|\u76F8\u5BF9\u4ECB\u8D28\u901F\u5EA6\u5E94\u4F4E\u4E8E\u58F0\u901F\u3002"),[R("Observed frequency|\u89C2\u6D4B\u9891\u7387",v.f*(v.c+v.o)/(v.c-v.s),"Hz")]),"Use f\u2092 = f\u209B(c+v\u2092)/(c\u2212v\u209B). f\u209B is emitted frequency, c is sound speed in the medium, v\u2092 is observer velocity toward the source, and v\u209B is source velocity toward the observer. Velocities share a unit; both moving speeds must be subsonic.|\u4F7F\u7528 f\u2092 = f\u209B(c+v\u2092)/(c\u2212v\u209B)\u3002f\u209B \u4E3A\u53D1\u5C04\u9891\u7387\uFF0Cc \u4E3A\u4ECB\u8D28\u58F0\u901F\uFF0Cv\u2092 \u4E3A\u89C2\u5BDF\u8005\u671D\u5411\u58F0\u6E90\u901F\u5EA6\uFF0Cv\u209B \u4E3A\u58F0\u6E90\u671D\u5411\u89C2\u5BDF\u8005\u901F\u5EA6\uFF1B\u901F\u5EA6\u4F7F\u7528\u76F8\u540C\u5355\u4F4D\uFF0C\u4E24\u4E2A\u8FD0\u52A8\u901F\u7387\u5747\u987B\u4F4E\u4E8E\u58F0\u901F\u3002",[1e4/9],"Collinear classical sound model in a stationary medium; positive velocities approach. Not relativistic light Doppler.|\u9759\u6B62\u4ECB\u8D28\u4E2D\u5171\u7EBF\u7ECF\u5178\u58F0\u5B66\u6A21\u578B\uFF0C\u63A5\u8FD1\u901F\u5EA6\u4E3A\u6B63\uFF1B\u4E0D\u662F\u5149\u7684\u76F8\u5BF9\u8BBA\u591A\u666E\u52D2\u6A21\u578B\u3002"),D("sound-intensity-level","Sound Intensity Level|\u58F0\u5F3A\u7EA7","Convert sound intensity to a reference-relative decibel level.|\u5C06\u58F0\u5F3A\u6362\u7B97\u4E3A\u76F8\u5BF9\u53C2\u8003\u503C\u7684\u5206\u8D1D\u7EA7\u3002",[p("x","Sound intensity (W/m\xB2)|\u58F0\u5F3A\uFF08W/m\xB2\uFF09",1e-6),n("r","Reference intensity (W/m\xB2)|\u53C2\u8003\u58F0\u5F3A\uFF08W/m\xB2\uFF09",1e-12,1e-30,1e15)],v=>[R("Sound intensity level|\u58F0\u5F3A\u7EA7",10*Math.log10(v.x/v.r),"dB")],"Use L = 10log\u2081\u2080(I/I\u1D63). I is sound intensity and I\u1D63 is reference intensity in the same unit. Sound intensity level L is in dB.|\u4F7F\u7528 L = 10log\u2081\u2080(I/I\u1D63)\u3002I \u4E3A\u58F0\u5F3A\uFF0CI\u1D63 \u4E3A\u540C\u5355\u4F4D\u53C2\u8003\u58F0\u5F3A\uFF1B\u58F0\u5F3A\u7EA7 L \u7684\u5355\u4F4D\u4E3A dB\u3002",[60],"Intensity level is not automatically A-weighted sound pressure or a hearing-exposure assessment.|\u58F0\u5F3A\u7EA7\u4E0D\u81EA\u52A8\u7B49\u4E8E A \u8BA1\u6743\u58F0\u538B\u7EA7\uFF0C\u4E5F\u4E0D\u662F\u542C\u529B\u66B4\u9732\u8BC4\u4F30\u3002"),D("combined-decibel-level","Combined Decibel Level|\u5206\u8D1D\u58F0\u7EA7\u53E0\u52A0","Add independent incoherent levels measured on the same basis.|\u53E0\u52A0\u4F7F\u7528\u76F8\u540C\u53E3\u5F84\u6D4B\u91CF\u7684\u72EC\u7ACB\u975E\u76F8\u5E72\u58F0\u7EA7\u3002",[text("x","Independent levels (dB)|\u5404\u72EC\u7ACB\u58F0\u7EA7\uFF08dB\uFF09","60,60")],v=>{const a=nums(v.x),m=Math.max(...a);return[R("Combined level|\u5408\u8BA1\u58F0\u7EA7",m+10*Math.log10(sum(a.map(x=>10**((x-m)/10)))),"dB")]},"Use L = 10log\u2081\u2080[\u03A310^(L\u1D62/10)]. L\u1D62 are independent incoherent levels in dB, sharing the same reference, weighting and location. The combined level L uses the same basis.|\u4F7F\u7528 L = 10log\u2081\u2080[\u03A310^(L\u1D62/10)]\u3002L\u1D62 \u4E3A\u72EC\u7ACB\u975E\u76F8\u5E72\u58F0\u7EA7\uFF08dB\uFF09\uFF0C\u987B\u4F7F\u7528\u76F8\u540C\u53C2\u8003\u3001\u8BA1\u6743\u4E0E\u4F4D\u7F6E\uFF1B\u5408\u8BA1\u58F0\u7EA7 L \u4F7F\u7528\u540C\u4E00\u53E3\u5F84\u3002",[63.01029995663981],"All levels must use the same reference, weighting and observation location. Coherent sources require phase information.|\u6240\u6709\u58F0\u7EA7\u5E94\u4F7F\u7528\u76F8\u540C\u53C2\u8003\u3001\u8BA1\u6743\u4E0E\u89C2\u6D4B\u4F4D\u7F6E\uFF1B\u76F8\u5E72\u58F0\u6E90\u8FD8\u9700\u76F8\u4F4D\u4FE1\u606F\u3002"),D("thin-lens","Thin Lens Image|\u8584\u900F\u955C\u6210\u50CF","Solve image distance and magnification using signed distances.|\u7528\u5E26\u7B26\u53F7\u8DDD\u79BB\u6C42\u50CF\u8DDD\u4E0E\u653E\u5927\u7387\u3002",[u("f","Focal length (cm), converging positive|\u7126\u8DDD\uFF08cm\uFF0C\u51F8\u900F\u955C\u4E3A\u6B63\uFF09",10),u("d","Object distance (cm), real object positive|\u7269\u8DDD\uFF08cm\uFF0C\u5B9E\u7269\u4E3A\u6B63\uFF09",30)],v=>{check(v.f!==0&&v.d!==0&&Math.abs(v.d-v.f)>1e-12,"Focal and object distances must be nonzero; an object at the focal plane forms an image at infinity.|\u7126\u8DDD\u4E0E\u7269\u8DDD\u975E\u96F6\uFF1B\u7269\u4F53\u5728\u7126\u5E73\u9762\u65F6\u50CF\u5728\u65E0\u7A77\u8FDC\u3002");const d=v.f*v.d/(v.d-v.f);return[R("Signed image distance|\u5E26\u7B26\u53F7\u50CF\u8DDD",d,"cm"),R("Lateral magnification|\u6A2A\u5411\u653E\u5927\u7387",-d/v.d)]},"Use 1/f = 1/d\u2092+1/d\u1D62 and m = \u2212d\u1D62/d\u2092. f is focal length, d\u2092 is object distance, and d\u1D62 is image distance in the same unit. A converging focal length and real object distance are positive; m is lateral magnification.|\u4F7F\u7528 1/f = 1/d\u2092+1/d\u1D62 \u53CA m = \u2212d\u1D62/d\u2092\u3002f \u4E3A\u7126\u8DDD\uFF0Cd\u2092 \u4E3A\u7269\u8DDD\uFF0Cd\u1D62 \u4E3A\u540C\u5355\u4F4D\u50CF\u8DDD\uFF1B\u4F1A\u805A\u900F\u955C\u7126\u8DDD\u548C\u5B9E\u7269\u7269\u8DDD\u4E3A\u6B63\uFF0Cm \u4E3A\u6A2A\u5411\u653E\u5927\u7387\u3002",[15,-.5],"Paraxial thin lens in air; positive image distance is real, negative is virtual. Aberrations and lens thickness excluded.|\u7A7A\u6C14\u4E2D\u8FD1\u8F74\u8584\u900F\u955C\u6A21\u578B\uFF0C\u50CF\u8DDD\u6B63\u4E3A\u5B9E\u50CF\u3001\u8D1F\u4E3A\u865A\u50CF\uFF1B\u5FFD\u7565\u50CF\u5DEE\u4E0E\u539A\u5EA6\u3002"),D("snells-law","Snell Refraction Angle|\u65AF\u6D85\u5C14\u6298\u5C04\u89D2","Apply refraction at a flat interface between two media.|\u8BA1\u7B97\u4E24\u4ECB\u8D28\u5E73\u9762\u754C\u9762\u7684\u6298\u5C04\u89D2\u3002",[p("a","Incident refractive index|\u5165\u5C04\u4ECB\u8D28\u6298\u5C04\u7387",1),p("b","Transmitted refractive index|\u900F\u5C04\u4ECB\u8D28\u6298\u5C04\u7387",1.5),n("t","Incident angle from normal (degrees)|\u4E0E\u6CD5\u7EBF\u5939\u89D2\uFF08\u5EA6\uFF09",30,0,90)],v=>{const s=v.a/v.b*Math.sin(rad(v.t));return[R("Refraction angle|\u6298\u5C04\u89D2",s>1?"Total internal reflection|\u5168\u5185\u53CD\u5C04":deg(Math.asin(s)),"\xB0")]},"Use n\u2081sin\u03B8\u2081 = n\u2082sin\u03B8\u2082. n\u2081 and n\u2082 are incident and transmitted refractive indices; \u03B8\u2081 and \u03B8\u2082 are angles from the normal. Angles are entered and displayed in degrees. If refraction has no real angle, the result identifies total internal reflection.|\u4F7F\u7528 n\u2081sin\u03B8\u2081 = n\u2082sin\u03B8\u2082\u3002n\u2081 \u4E0E n\u2082 \u4E3A\u5165\u5C04\u53CA\u900F\u5C04\u4ECB\u8D28\u6298\u5C04\u7387\uFF0C\u03B8\u2081 \u4E0E \u03B8\u2082 \u4E3A\u76F8\u5BF9\u6CD5\u7EBF\u7684\u5939\u89D2\uFF1B\u8F93\u5165\u548C\u663E\u793A\u89D2\u5EA6\u5747\u4F7F\u7528\u5EA6\uFF0C\u82E5\u4E0D\u5B58\u5728\u5B9E\u6570\u6298\u5C04\u89D2\uFF0C\u7ED3\u679C\u6807\u793A\u5168\u5185\u53CD\u5C04\u3002",[19.47122063449069]),D("critical-angle","Critical Angle|\u5168\u53CD\u5C04\u4E34\u754C\u89D2","Find the critical angle from a denser optical medium.|\u6C42\u7531\u9AD8\u6298\u5C04\u7387\u4ECB\u8D28\u5C04\u51FA\u7684\u5168\u53CD\u5C04\u4E34\u754C\u89D2\u3002",[p("a","Incident refractive index|\u5165\u5C04\u4ECB\u8D28\u6298\u5C04\u7387",1.5),p("b","Transmitted refractive index|\u900F\u5C04\u4ECB\u8D28\u6298\u5C04\u7387",1)],v=>(check(v.a>v.b,"Critical angle requires incident index greater than transmitted index.|\u4E34\u754C\u89D2\u8981\u6C42\u5165\u5C04\u4ECB\u8D28\u6298\u5C04\u7387\u5927\u4E8E\u900F\u5C04\u4ECB\u8D28\u3002"),[R("Critical angle from normal|\u4E0E\u6CD5\u7EBF\u4E34\u754C\u5939\u89D2",deg(Math.asin(v.b/v.a)),"\xB0")]),"Use \u03B8 = asin(n\u2082/n\u2081). n\u2081 is incident refractive index and n\u2082 is transmitted refractive index, with n\u2081 > n\u2082. The critical angle is measured from the normal and displayed in degrees.|\u4F7F\u7528 \u03B8 = asin(n\u2082/n\u2081)\u3002n\u2081 \u4E3A\u5165\u5C04\u4ECB\u8D28\u6298\u5C04\u7387\uFF0Cn\u2082 \u4E3A\u900F\u5C04\u4ECB\u8D28\u6298\u5C04\u7387\uFF0C\u5E76\u8981\u6C42 n\u2081 > n\u2082\uFF1B\u4E34\u754C\u89D2\u76F8\u5BF9\u6CD5\u7EBF\u6D4B\u91CF\uFF0C\u4EE5\u5EA6\u663E\u793A\u3002",[41.810314895778596]),D("photon-energy","Photon Energy|\u5149\u5B50\u80FD\u91CF","Convert vacuum wavelength into single-photon energy.|\u5C06\u771F\u7A7A\u6CE2\u957F\u6362\u7B97\u4E3A\u5355\u5149\u5B50\u80FD\u91CF\u3002",[p("l","Vacuum wavelength (nm)|\u771F\u7A7A\u6CE2\u957F\uFF08nm\uFF09",500)],v=>{const energy=h*c/(v.l*1e-9);return[R("Photon energy|\u5149\u5B50\u80FD\u91CF",energy,"J"),R("Photon energy in electronvolts|\u7535\u5B50\u4F0F\u80FD\u91CF",energy/eV,"eV"),R("Frequency|\u9891\u7387",c/(v.l*1e-9),"Hz")]},"E=hc/\u03BB; f=c/\u03BB",[3972891714297857e-34,2.479683968664005,599584916e6]),D("de-broglie-wavelength","De Broglie Wavelength|\u5FB7\u5E03\u7F57\u610F\u6CE2\u957F","Estimate nonrelativistic matter wavelength from mass and speed.|\u7531\u8D28\u91CF\u4E0E\u901F\u7387\u4F30\u8BA1\u975E\u76F8\u5BF9\u8BBA\u7269\u8D28\u6CE2\u957F\u3002",[p("m","Mass in units of 10\u207B\xB3\u2070 kg|\u8D28\u91CF\uFF0810\u207B\xB3\u2070 kg\uFF09",.91093837015),p("v","Speed (m/s)|\u901F\u7387\uFF08m/s\uFF09",1e6)],v=>(check(v.v<c*.1,"Use speed below 0.1c for this nonrelativistic approximation.|\u6B64\u975E\u76F8\u5BF9\u8BBA\u8FD1\u4F3C\u8981\u6C42\u901F\u7387\u4F4E\u4E8E 0.1c\u3002"),[R("Matter wavelength|\u7269\u8D28\u6CE2\u957F",h/(v.m*1e-30*v.v)*1e9,"nm")]),"\u03BB=h/(mv)",[.727389510325698]),D("diffraction-grating","Diffraction Grating Angle|\u5149\u6805\u884D\u5C04\u89D2","Find the angle of a diffraction order at normal incidence.|\u6C42\u5782\u76F4\u5165\u5C04\u5149\u6805\u7684\u6307\u5B9A\u7EA7\u6B21\u884D\u5C04\u89D2\u3002",[p("d","Slit spacing (\xB5m)|\u7F1D\u8DDD\uFF08\xB5m\uFF09",1),p("l","Wavelength (nm)|\u6CE2\u957F\uFF08nm\uFF09",500),i("m","Diffraction order|\u884D\u5C04\u7EA7\u6B21",1,-1e3,1e3)],v=>{const s=v.m*v.l/(1e3*v.d);return check(Math.abs(s)<=1,"This order cannot propagate: |m\u03BB/d| exceeds 1.|\u8BE5\u7EA7\u6B21\u4E0D\u80FD\u4F20\u64AD\uFF1A|m\u03BB/d| \u5927\u4E8E 1\u3002"),[R("Diffraction angle|\u884D\u5C04\u89D2",deg(Math.asin(s)),"\xB0")]},"Use d sin\u03B8 = m\u03BB. d is slit spacing, \u03BB is wavelength converted to the same length unit, and m is diffraction order. The angle is displayed in degrees; an order beyond the real-angle range is rejected.|\u4F7F\u7528 d sin\u03B8 = m\u03BB\u3002d \u4E3A\u7F1D\u8DDD\uFF0C\u03BB \u4E3A\u6362\u7B97\u81F3\u76F8\u540C\u957F\u5EA6\u5355\u4F4D\u7684\u6CE2\u957F\uFF0Cm \u4E3A\u884D\u5C04\u7EA7\u6B21\uFF1B\u89D2\u5EA6\u4EE5\u5EA6\u663E\u793A\uFF0C\u8D85\u51FA\u5B9E\u6570\u89D2\u5EA6\u8303\u56F4\u7684\u7EA7\u6B21\u4F1A\u88AB\u62D2\u7EDD\u3002",[30])})();
